// FCAL embedded form - Premium Care (Industrial) page
// Form/script sourced from experiment 5222024402960384.
// Adapted for this page: insertion point, centered wrapper, jump-link CTA.
// ---------------------------------------------------------------------------

const WRAPPER_ID = 'premium-care-form-wrapper';
const CTA_SELECTOR = 'a[href*="DemoContactRequest"]';

// Get current page URL
const currentPageUrl = window.location.href;

// ---------------------------------------------------------------------------
// lcid / lrpf mapping removed -- these params are now baked into the iframe URL
// directly. Kept commented for reference.
// ---------------------------------------------------------------------------
